fn cmd_run(args: &[String]) {
    let mut actions = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--sample" => actions.push(Action::Sample),
            "--highrise" => actions.push(Action::Highrise),
            "--cmd" | "--script" | "--save" => {
                if i + 1 >= args.len() {
                    usage_exit(Some(format!("{} needs a value", a)));
                }
                let v = args[i + 1].clone();
                i += 1;
                actions.push(match a.as_str() {
                    "--cmd" => Action::Cmd(v),
                    "--script" => Action::Script(v),
                    _ => Action::Save(v),
                });
            }
            _ if a.starts_with("--") => usage_exit(Some(format!("unknown option `{}`", a))),
            _ => actions.push(Action::Open(a.clone())),
        }
        i += 1;
    }
    let mut s = session::Session::new();
    for act in actions {
        match act {
            Action::Open(path) => match commands::open_path(&mut s, &path) {
                Ok(v) => println!("{}", v.sorted().to_compact()),
                Err(e) => {
                    // a Revit import's error is a whole message, the path first
                    if rvt::is_revit_path(&path) {
                        eprintln!("{}", e);
                    } else {
                        eprintln!("open: {}", e);
                    }
                    exit(1);
                }
            },
            Action::Sample => {
                if let Err(e) = commands::build_sample(&mut s) {
                    eprintln!("{}", e);
                    exit(1);
                }
            }
            Action::Highrise => match commands::build_highrise(&mut s, 20) {
                Ok(v) => println!("{}", v.sorted().to_compact()),
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            },
            Action::Cmd(text) => run_script_text(&mut s, &text),
            Action::Script(path) => match std::fs::read(&path) {
                Ok(bytes) => {
                    let text = String::from_utf8_lossy(&bytes).to_string();
                    run_script_text(&mut s, &text)
                }
                Err(e) => {
                    eprintln!("{}: {}", path, commands::io_err(&e));
                    exit(1);
                }
            },
            Action::Save(path) => {
                let p = json::Value::Obj({
                    let mut m = json::Map::new();
                    m.insert("path", json::Value::s(&path));
                    m
                });
                match s.execute("save", &p) {
                    Ok(v) => println!("{}", v.sorted().to_compact()),
                    Err(e) => {
                        eprintln!("save: {}", e);
                        exit(1);
                    }
                }
            }
        }
    }
}

fn run_script_text(s: &mut session::Session, text: &str) {
    let lines = match script::parse(text) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };
    // a script's replies are printed once all of it has gone through
    let mut out = String::new();
    for l in lines {
        match s.execute(&l.id, &l.params) {
            Ok(v) => {
                out.push_str(&v.sorted().to_compact());
                out.push('\n');
            }
            Err(e) => {
                eprintln!("line {} ({}): {}", l.line, l.id, e);
                exit(1);
            }
        }
    }
    print!("{}", out);
}

fn cmd_info(path: &str) {
    match commands::info(path) {
        Ok(v) => println!("{}", v.sorted().to_pretty()),
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    }
}

fn cmd_convert(input: &str, output: &str) {
    let mut s = session::Session::new();
    match commands::open_path(&mut s, input) {
        Ok(_) => {}
        Err(e) => {
            // a Revit import's error is a whole message, the path first
            if rvt::is_revit_path(input) {
                eprintln!("{}", e);
            } else {
                eprintln!("open: {}", e);
            }
            exit(1);
        }
    }
    let mut m = json::Map::new();
    m.insert("path", json::Value::s(output));
    match s.execute("save", &json::Value::Obj(m)) {
        Ok(v) => println!("{}", v.sorted().to_compact()),
        Err(e) => {
            eprintln!("save: {}", e);
            exit(1);
        }
    }
}
//! Scripts: one `id {json}` per line; blank lines and `#` comments are passed over.

use crate::json::Value;

pub struct Line {
    pub line: usize,
    pub id: String,
    pub params: Value,
}

/// Parses a whole script before anything runs, so a bad line stops it at once.
pub fn parse(text: &str) -> Result<Vec<Line>, String> {
    let mut out = Vec::new();
    for (n, raw) in text.lines().enumerate() {
        let t = raw.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        let (id, rest) = match t.find(char::is_whitespace) {
            Some(i) => (&t[..i], t[i..].trim()),
            None => (t, ""),
        };
        let params = if rest.is_empty() {
            Value::obj()
        } else {
            match crate::json::parse(rest) {
                Ok(v) => v,
                Err(e) => return Err(format!("line {}: bad JSON after `{}`: {}", n + 1, id, e)),
            }
        };
        out.push(Line { line: n + 1, id: id.to_string(), params });
    }
    Ok(out)
}
//! Reading the model: `inspect` and `elements`.

use crate::json::{Map, Value};
use crate::session::Session;

pub fn inspect(s: &Session) -> Value {
    let pr = &s.project;
    let mut m = Map::new();
    let mut counts = Map::new();
    for e in pr.elements.values() {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        let n = counts.get(&c).and_then(|v| v.as_u64()).unwrap_or(0);
        counts.insert(&c, Value::u(n + 1));
    }
    m.insert("counts", Value::Obj(counts));
    m.insert("history", s.history().into());
    m.insert("language", pr.language().into());
    m.insert("name", pr.name().into());
    let levels: Vec<Value> = crate::commands::basic::level_ids_sorted(pr)
        .iter()
        .map(|id| {
            let e = pr.el(*id).unwrap();
            jobj! {"elevation" => e.get("elevation").cloned().unwrap_or(Value::Null), "id" => *id, "name" => e.get("name").cloned().unwrap_or(Value::Null)}
        })
        .collect();
    m.insert("levels", Value::Arr(levels));
    for (k, v) in crate::styles::inspect_entries(s) {
        m.insert(&k, v);
    }
    Value::Obj(m)
}

pub fn elements(s: &Session, p: &Value) -> Result<Value, String> {
    let pr = &s.project;
    let cat = p.get("category").and_then(|c| c.as_str()).map(|c| c.to_string());
    let mut out = Vec::new();
    for (id, e) in &pr.elements {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        if let Some(want) = &cat {
            if c != want {
                continue;
            }
        }
        let mut x = e.clone();
        x.set("id", Value::u(*id));
        if c == "level" {
            x.set("computation_height", Value::f(1200.0));
        }
        if c == "pointcloud" {
            crate::cloud::element_view(pr, &mut x);
        }
        out.push(x);
    }
    let n = out.len();
    Ok(jobj! {"count" => n, "elements" => Value::Arr(out), "returned" => n})
}
//! Reading a project file into a project.

use crate::json::Value;
use crate::project::Project;

pub fn load(v: Value) -> Result<Project, String> {
    if !matches!(v, Value::Obj(_)) {
        return Err(format!("invalid type: {}, expected struct ProjectFile", v.kind_name()));
    }
    let mut p = Project::from_value(v);
    crate::cloud::load(&mut p)?;
    Ok(p)
}

